create function public.cp_people(o uuid) returns jsonb language sql stable security invoker set search_path=public as $$ select coalesce(jsonb_agg(jsonb_build_object('id',user_id,'role',role,'label',role||' · '||left(user_id::text,8)) order by role),'[]') from memberships where org_id=o $$;
create function public.cp_context(b uuid) returns jsonb language plpgsql stable security invoker set search_path=public as $$ declare r records;begin select * into r from records where id=b and kind='batch';if not cp_access(r.org_id,b) then raise exception 'Not accessible';end if;return jsonb_build_object('farm',r.data->>'farm','shed',r.data->>'shed','farmName',(select data->>'name' from records where id=(r.data->>'farm')::uuid),'shedName',(select data->>'name' from records where id=(r.data->>'shed')::uuid),'batchName',r.data->>'name');end $$;
revoke all on function cp_people(uuid),cp_context(uuid) from public,anon;
grant execute on function cp_people(uuid),cp_context(uuid) to authenticated;
create or replace function public.cp_num(p jsonb,k text,est boolean default false) returns numeric language sql immutable set search_path=public as $$ select case when p#>>array['values',k,'value'] is not null and ((p#>>array['values',k,'state']='measured' and p#>>array['values',k,'method'] in ('manual','sensor')) or est and (p#>>array['values',k,'state']='estimated' or p#>>array['values',k,'method']='estimated')) then (p#>>array['values',k,'value'])::numeric end $$;
